const BY_ID: ReadonlyMap<string, Topic> = new Map(TOPICS.map((topic) => [topic.topicId, topic]));

/** The registry entry for a topic ID, or undefined when it is not registered. */
export function topicById(topicId: string): Topic | undefined {
  return BY_ID.get(topicId);
}
